def normalized_text(text):
    return re.sub(r"\s+", "", text.replace("\u00ad", "").replace("\u200b", ""))


def translation_text_map(text, wrapped_words=()):
    """Normalize typography only, retaining offsets into the actual PDF text."""
    normalized, offsets = [], []
    omitted = {
        match.start() + len(match.group(1))
        for match in re.finditer(r"(?<!\w)([A-Za-z]+)-\s*([A-Za-z]+)(?!\w)", text)
        if match.group(1) + match.group(2) in wrapped_words
    }
    for offset, char in enumerate(text):
        if offset in omitted:
            continue
        for part in unicodedata.normalize("NFKC", char):
            if part.isspace() or part in "\u00ad\u200b":
                continue
            normalized.append(part.translate(str.maketrans("‘’“”", "''\"\"")))
            offsets.append(offset)
    return "".join(normalized), offsets


def closest_span(original, source, cursor, similarity=0.93, whole=False):
    """Where `original` was copied from, allowing small changes: (start, end) in
    `source`. Near `cursor` unless `whole`, which looks through all of `source`."""
    if len(original) < 12:
        return None
    window = (
        source[cursor:] if whole else source[cursor : cursor + len(original) * 2 + 400]
    )
    blocks = [
        b
        for b in difflib.SequenceMatcher(
            None, original, window, autojunk=False
        ).get_matching_blocks()
        if b.size
    ]
    if not blocks or sum(b.size for b in blocks) < similarity * len(original):
        return None
    start = cursor + max(0, blocks[0].b - blocks[0].a)
    end = cursor + min(
        len(window),
        blocks[-1].b
        + blocks[-1].size
        + (len(original) - blocks[-1].a - blocks[-1].size),
    )
    return (start, end) if end > start else None


def wrapped_words_of(text):
    # Only join words actually hyphenated across a line break in this PDF.
    # Do not normalize arbitrary hyphens (e.g. subtraction or re-sign/resign).
    return {
        m.group(1) + m.group(2)
        for m in re.finditer(
            r"(?<!\w)([A-Za-z]+)-[ \t]*\n[ \t]*([A-Za-z]+)(?!\w)", text
        )
    }


def realign_originals(result, text, ordered=True):
    """Point a paragraph whose original the model changed slightly back at the
    page's own words. A model that "fixes" the paper's grammar or shortens a row
    of dot leaders has still pointed at that stretch of the page; the reader
    looks for the original there, so it is the page's text that is kept. A
    paragraph that is really elsewhere or invented is left for verification to
    reject."""
    wrapped = wrapped_words_of(text)
    source, offsets = translation_text_map(text, wrapped)
    cursor = 0
    for paragraph in result.paragraphs:
        original, _ = translation_text_map(paragraph.original, wrapped)
        position = source.find(original, cursor)
        if original and position < 0 and not ordered:
            position = source.find(original)
        if original and position < 0:
            span = closest_span(original, source, cursor)
            if not span and not ordered:
                span = closest_span(original, source, 0, whole=True)
            if span:
                paragraph.original = text[offsets[span[0]] : offsets[span[1] - 1] + 1]
                position, original = span[0], source[span[0] : span[1]]
        if original and position >= 0:
            end = position + len(original)
            cursor = end if ordered else max(cursor, end)


def verify_translation(result, text, ordered=True):
    """`ordered`: the paragraphs follow the page's text in order. A table or a
    contents page can be read in a different order than its text layer lists it,
    so the reader's own order is accepted when this is False; every paragraph
    must still be on the page and together they must cover it."""
    wrapped_words = wrapped_words_of(text)
    source, offsets = translation_text_map(text, wrapped_words)
    cursor, covered = 0, bytearray(len(source))
    for paragraph in result.paragraphs:
        if paragraph.kind == "page_number" and not re.fullmatch(
            r"(?:[0-9]+|[ivxlcdmIVXLCDM]+)", paragraph.original.strip()
        ):
            raise ValueError("页码分类包含正文，请重试")
        original, _ = translation_text_map(paragraph.original, wrapped_words)
        position = source.find(original, cursor)
        if original and position < 0 and not ordered:
            position = source.find(original)
        if not original or position < 0:
            raise ValueError("译文中的原句与指定页面不一致，请重试")
        end = position + len(original)
        cursor = end if ordered else max(cursor, end)
        covered[position:end] = b"\x01" * len(original)
        # Never retain the model's typographic substitutions as PDF evidence.
        paragraph.original = text[offsets[position] : offsets[end - 1] + 1]
    if not source or sum(covered) / len(source) < 0.95:
        raise ValueError("本页译文不完整，请重试")


def normalize_guide(value):
    """Three sentences squeezed into one summary item are still three sentences."""
    summary = value.get("summary") if isinstance(value, dict) else None
    if (
        isinstance(summary, list)
        and 0 < len(summary) < 3
        and all(isinstance(item, str) for item in summary)
    ):
        sentences = [
            s
            for s in re.findall(r"[^。！？!?]+[。！？!?]?", "".join(summary))
            if s.strip()
        ]
        if len(sentences) >= 3:
            return {**value, "summary": sentences[:2] + ["".join(sentences[2:])]}
    return value


CITATION_RULES = (
    "逐句出处：章节 body 与摘要里每一句陈述论文内容的话，句末紧跟一个出处标记，"
    "格式 [[p页码: 「原文」]]，例如 [[p3: 「we reduce latency by 40%」]]（用「」而不是英文双引号，"
    "免得破坏 JSON）。页码是该原文所在的PDF页（与上文「【第 N 页】」一致）；「」里的原文必须逐字复制自该页文字，"
    "是其中一个连续片段（只允许调整空白和换行），不超过300字，不改写、不翻译、不拼接、不省略，"
    "挑能直接支持这一句的那一句原文，原文含英文双引号时改选不含的一句。"
    "一句话如依据多处原文，就紧跟多个标记。不要在标题或关键词里写标记；"
    "找不到可逐字引用的原文时，这一句不加标记，不要编造引文。"
)


def verify_guide(guide, evidence_text):
    """Keep only the citations that are really on the pages the model read.

    A quote found on another page than the one named gets that page; one found
    nowhere is dropped with its sentence kept. A section's `pages` become the
    pages its verified citations are on (those the model listed stay for a
    section it cited nothing in)."""
    pages = {
        int(number): text
        for number, text in (evidence_text or {}).items()
        if str(number).isdigit() and isinstance(text, str)
    }
    guide.summary = [verify(line, pages)[0] or line for line in guide.summary]
    for section in guide.sections:
        body, kept = verify(section.body, pages)
        section.body = body.strip() or section.body
        if kept:
            section.pages = sorted({page for page, _ in kept})
    guide.cited = True


